-- Links to records are https addresses, not URNs: `[Label](keep:page/<id>)` becomes `[Label](https://keep.example.com/p/<id>)`, a person's and a group's People's own.
UPDATE "comment" SET "body" = regexp_replace(regexp_replace(regexp_replace("body", '\]\(keep:page/([0-9a-fA-F-]{36})\)', '](https://keep.example.com/p/\1)', 'g'), '\]\(people:person/([0-9a-fA-F-]{36})\)', '](https://people.example.com/p/\1)', 'g'), '\]\(people:group/([0-9a-fA-F-]{36})\)', '](https://people.example.com/g/\1)', 'g') WHERE "body" ~ '\]\((keep:page|people:person|people:group)/';
--> statement-breakpoint
UPDATE "notification" SET "text" = regexp_replace(regexp_replace(regexp_replace("text", '\]\(keep:page/([0-9a-fA-F-]{36})\)', '](https://keep.example.com/p/\1)', 'g'), '\]\(people:person/([0-9a-fA-F-]{36})\)', '](https://people.example.com/p/\1)', 'g'), '\]\(people:group/([0-9a-fA-F-]{36})\)', '](https://people.example.com/g/\1)', 'g') WHERE "text" ~ '\]\((keep:page|people:person|people:group)/';
